    private void btnVerRutinaActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnVerRutinaActionPerformed
    if (ventanaRutina == null || ventanaRutina.getRutina() == null) {
    javax.swing.JOptionPane.showMessageDialog(this, "Primero debe crear una rutina");
    return;
}
 String ejercicios = ventanaRutina.getRutina().obtenerEjercicios();
javax.swing.JOptionPane.showMessageDialog(this, ejercicios);     
        
        
        
        
    }//GEN-LAST:event_btnVerRutinaActionPerformed

